import { readFileSync, writeFileSync } from 'node:fs';
import { replacements } from './vendor/frontend/pretty-text/addon/emoji/data.js';

const output = new URL('../lib/src/generated_emoji_unicode.dart', import.meta.url);
const dart = [
  '// Generated by js/generate-emoji-unicode.mjs from Discourse’s vendored emoji data.',
  'const discourseEmojiUnicode = <String, String>{',
  ...Object.entries(replacements).map(([glyph, name]) => {
    const escaped = Array.from(glyph, char => `\\u{${char.codePointAt(0).toString(16)}}`).join('');
    const entry = `  '${escaped}': '${name}',`;
    return entry.length <= 80 ? entry : `  '${escaped}':\n      '${name}',`;
  }),
  '};',
  '',
].join('\n');
if (process.argv.includes('--check')) {
  if (readFileSync(output, 'utf8') !== dart) throw new Error('Regenerate the emoji Unicode table');
} else {
  writeFileSync(output, dart);
}
